 {page==='overview'&&<><section className=\"welcome-banner\"><div className=\"welcome-copy\"><span className=\"eyebrow\"><span/> ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО</span><Text as=\"h2\" variant=\"display-1\">Меньше хаоса.<br/>Больше движения вперёд.</Text><p>Планируйте, создавайте и достигайте целей.<br/>Все ваши проекты — на одной орбите.</p><Button view=\"action\" size=\"l\" onClick={()=>navigate('projects')}>К моим проектам <Icon data={ArrowRight} size={16}/></Button></div><OrbitArt/><span className=\"banner-caption\">Большие результаты начинаются с маленьких шагов.</span></section>
 <section className=\"metrics\" aria-label=\"Статистика пространства\">{[{label:'Всего проектов',value:String(projects.length).padStart(2,'0'),icon:Folder,color:'purple',note:'+2 за этот месяц',positive:true},{label:'В работе',value:String(projects.filter(p=>p.status==='В работе').length).padStart(2,'0'),icon:Clock,color:'blue',note:'Идеи превращаются в результат'},{label:'Завершено задач',value:projects.reduce((a,p)=>a+p.done,0),icon:CircleCheck,color:'green',note:'+12 за эту неделю',positive:true},{label:'Участников команды',value:'08',icon:Persons,color:'orange',note:'Вместе получается больше'}].map(m=><div className=\"metric-card\" key={m.label}><div className=\"row between\"><span className=\"muted\">{m.label}</span><span className={"'`metric-icon ${m.color}`}><Icon data={m.icon} size={19}/></span></div><Text variant="display-2" className="metric-value">{m.value}</Text><span className={`metric-note ${m.positive?'"'positive':''}"'`}>{m.positive&&<Icon data={ArrowUpRight} size={13}/>} {m.note}</span></div>)}</section>
 <section className="recent-projects"><div className="section-heading"><div className="row"><Text as="h2" variant="header-1">Недавние проекты</Text><span className="count-pill">{projects.length}</span></div><Button view="flat" onClick={()=>navigate('"'projects')}>Все проекты <Icon data={ArrowRight} size={15}/></Button></div><div className=\"project-grid\">{projects.slice(0,3).map(projectCard)}</div></section>
 <section className=\"activity-panel\"><div className=\"section-heading\"><Text as=\"h2\" variant=\"header-1\">Последняя активность</Text><Button view=\"flat\" onClick={()=>setAllActivity("'!allActivity)}>{allActivity?'"'Свернуть':'Вся активность'}<Icon data={ArrowRight} size={15}/></Button></div><div className=\"activity-list\">{activity.slice(0,allActivity?4:3).map((a,i)=><div className=\"activity-row\" key={i}><Avatar name={a.name} color={a.color}/><div className=\"activity-body\"><p><strong>{a.name}</strong> <span className=\"muted\">{a.text}</span> <strong>«{a.subject}»</strong></p><span className=\"muted\">{a.project}</span></div><span className=\"activity-time\">{a.time}</span></div>)}</div></section></>}
 {page==='projects'&&<><div className=\"project-toolbar\"><div className=\"filter-tabs\">{['Все проекты','В работе','На проверке','Завершён'].map(f=><Button key={f} view={f===filter?'normal':'flat'} selected={f===filter} onClick={()=>setFilter(f)}>{f}</Button>)}</div><div className=\"search-controls\"><TextInput size=\"l\" placeholder=\"Найти проект...\" value={search} onUpdate={setSearch} hasClear startContent={<Icon data={Magnifier} size={16}/>} controlProps={{'aria-label':'Поиск проектов'}}/><Button view=\"outlined\" size=\"l\" selected={listView} onClick={()=>setListView("'!listView)} aria-label="Переключить вид списка"><Icon data={ListUl} size={18}/></Button></div></div><div className={`project-grid all-projects ${listView?'"'list-view':''}"'`}>{filtered.map(projectCard)}</div>{filtered.length===0&&<div className="empty-state"><Icon data={Magnifier} size={36}/><Text as="h2" variant="header-1">Проекты не найдены</Text><p className="muted">Попробуйте изменить запрос или выбрать другой статус.</p><Button view="outlined" onClick={()=>{setSearch('"'');setFilter('Все проекты');}}>Сбросить фильтры</Button></div>}</>}
 {page==='settings'&&<div className=\"settings-layout\"><form className=\"settings-card\" onSubmit={e=>{e.preventDefault();if("'!draft.name.trim())return;setProfile(draft);setToast('"'Настройки сохранены');}}><Text as=\"h2\" variant=\"header-1\">Профиль и пространство</Text><p className=\"muted\">Так вас будут видеть другие участники команды.</p><div className=\"profile-preview\"><Avatar name={draft.name||'А'}/><span><strong>{draft.name}</strong><br/><span className=\"muted\">Ваш личный профиль</span></span></div><label className=\"field-label\" htmlFor=\"profile-name\">Ваше имя</label><TextInput id=\"profile-name\" value={draft.name} onUpdate={name=>setDraft({...draft,name})} size=\"l\" controlProps={{required:true,maxLength:50}}/><label className=\"field-label\" htmlFor=\"email\">Электронная почта</label><TextInput id=\"email\" type=\"email\" value={draft.email} onUpdate={email=>setDraft({...draft,email})} size=\"l\" controlProps={{required:true}}/><label className=\"field-label\" htmlFor=\"workspace\">Название пространства</label><TextInput id=\"workspace\" value={draft.workspace} onUpdate={workspace=>setDraft({...draft,workspace})} size=\"l\" controlProps={{required:true,maxLength:60}}/><Button type=\"submit\" view=\"action\" size=\"l\" className=\"save-button\">Сохранить изменения</Button></form><div className=\"settings-stack\"><section className=\"settings-card\"><Text as=\"h2\" variant=\"header-1\">Внешний вид</Text><p className=\"muted\">Выберите комфортную тему оформления.</p><div className=\"theme-options\">{(['light','dark'] as const).map(t=><Button key={t} size=\"xl\" view={theme===t?'outlined-action':'outlined'} selected={theme===t} onClick={()=>setTheme(t)}><Icon data={t==='light'?Sun:Moon} size={20}/>{t==='light'?'Светлая':'Тёмная'}{theme===t&&<Icon data={CircleCheck} size={16}/>}</Button>)}</div><span className=\"settings-hint\">Тема сохраняется для следующего визита.</span></section><section className=\"settings-card\"><Text as=\"h2\" variant=\"header-1\">Уведомления</Text><div className=\"notification-setting\"><div><strong>Активность в пространстве</strong><p className=\"muted\">Показывать индикатор новых событий</p></div><Switch checked={notifications} onUpdate={setNotifications} title=\"Уведомления об активности\"/></div></section></div></div>}
 <footer className=\"page-footer\"><span>Орбита · Пространство для ваших идей</span><span><span className=\"system-dot\"/> Всё работает в штатном режиме</span></footer></main></div>}/>
 <Modal open={creating} onOpenChange={setCreating} aria-label=\"Создание проекта\"><form className=\"modal-body\" onSubmit={createProject}><div className=\"section-heading\"><Text variant=\"header-1\">Новый проект</Text><Button view=\"flat\" onClick={()=>setCreating(false)} aria-label=\"Закрыть\"><Icon data={Xmark} size={18}/></Button></div><p className=\"muted\">Дайте вашей следующей идее своё пространство.</p><label className=\"field-label\" htmlFor=\"new-name\">Название проекта</label><TextInput id=\"new-name\" size=\"l\" value={name} onUpdate={v=>{setName(v);setError('');}} placeholder=\"Например, запуск нового продукта\" autoFocus errorMessage={error} validationState={error?'invalid':undefined} controlProps={{maxLength:80}}/><label className=\"field-label\" htmlFor=\"new-description\">Описание</label><TextArea id=\"new-description\" value={description} onUpdate={setDescription} rows={3} placeholder=\"Чего вы хотите достичь?\" controlProps={{maxLength:250}}/><span className=\"field-label\">Направление</span><Flex gap={2} wrap=\"wrap\">{['Дизайн','Разработка','Маркетинг','Команда'].map(c=><Button key={c} selected={c===category} view={c===category?'outlined-action':'outlined'} onClick={()=>setCategory(c)}>{c}</Button>)}</Flex><div className=\"modal-actions\"><Button size=\"l\" onClick={()=>setCreating(false)}>Отмена</Button><Button size=\"l\" view=\"action\" type=\"submit\">Создать проект</Button></div></form></Modal>
 <Modal open={"'!!selected} onOpenChange={open=>!open&&setSelected(null)} aria-label="Информация о проекте">{selected&&<div className="modal-body"><div className="section-heading"><ProjectIcon project={selected}/><Button view="flat" onClick={()=>setSelected(null)} aria-label="Закрыть"><Icon data={Xmark} size={18}/></Button></div><Text as="h2" variant="header-2">{selected.name}</Text><p className="muted">{selected.description}</p><div className="detail-row"><span>Направление</span><strong>{selected.category}</strong></div><div className="detail-row"><span>Срок</span><strong>{selected.date}</strong></div><div className="detail-row"><span>Задачи</span><strong>{selected.done} из {selected.tasks} завершено</strong></div><div className="detail-row"><span>Статус</span><strong>{selected.status}</strong></div><div className="modal-actions"><Button onClick={()=>setSelected(null)} size="l">Закрыть</Button><Button view="action" size="l" onClick={()=>{const status=selected.status==='"'Завершён'?'В работе':'Завершён';setProjects(projects.map(p=>p.id===selected.id?{...p,status,progress:status==='Завершён'?100:0,done:status==='Завершён'?p.tasks:0}:p));setSelected(null);setToast('Статус проекта обновлён');}}>{selected.status==='Завершён'?'Вернуть в работу':'Завершить проект'}</Button></div></div>}</Modal>
 <Modal open={help} onOpenChange={setHelp} aria-label=\"О пространстве\"><div className=\"modal-body\"><div className=\"section-heading\"><Text variant=\"header-1\">Добро пожаловать на Орбиту</Text><Button view=\"flat\" onClick={()=>setHelp(false)} aria-label=\"Закрыть\"><Icon data={Xmark} size={18}/></Button></div><p className=\"help-intro\">Маленькое пространство для больших идей.</p><div className=\"help-step\"><Icon data={House} size={22}/><div><strong>Держите руку на пульсе</strong><p className=\"muted\">Обзор собирает проекты, прогресс и события команды.</p></div></div><div className=\"help-step\"><Icon data={Folder} size={22}/><div><strong>Дайте идее старт</strong><p className=\"muted\">Создайте проект, выберите направление и следите за результатом.</p></div></div><div className=\"help-step\"><Icon data={Gear} size={22}/><div><strong>Настройте под себя</strong><p className=\"muted\">Обновите профиль и выберите светлую или тёмную тему.</p></div></div><p className=\"muted\">Данные этого демо сохраняются в вашем браузере.</p><Button view=\"action\" size=\"l\" width=\"max\" onClick={()=>{setHelp(false);openCreate();}}>Создать первый проект</Button></div></Modal>
 <Modal open={showNotifications} onOpenChange={setShowNotifications} aria-label=\"Уведомления\"><div className=\"modal-body\"><div className=\"section-heading\"><Text variant=\"header-1\">Уведомления</Text><Button view=\"flat\" onClick={()=>setShowNotifications(false)} aria-label=\"Закрыть\"><Icon data={Xmark} size={18}/></Button></div>{activity.slice(0,3).map(a=><div className=\"notification-row\" key={a.name}><Avatar name={a.name} color={a.color}/><div><strong>{a.name}</strong><p>{a.text} «{a.subject}»</p><span className=\"muted\">{a.time}</span></div></div>)}</div></Modal>
 {toast&&<div className=\"toast\" role=\"status\"><Icon data={CircleCheck} size={19}/>{toast}</div>}
 </ThemeProvider>;
