import {ArrowRight, ArrowUpRight, Bell, Calendar, ChevronDown, CircleCheck, CircleQuestion, Clock, Folder, Gear, Globe, House, Layers, ListUl, Magnifier, Moon, Palette, Persons, Plus, Rocket, Smartphone, Sun, Xmark} from '@gravity-ui/icons';
import './styles.css';

type Page = 'overview' | 'projects' | 'settings';
type Project = {id: string; name: string; description: string; category: string; status: string; progress: number; tasks: number; done: number; color: string; date: string};
const initialProjects: Project[] = [
  {id:'1', name:'Редизайн сайта', description:'Новый взгляд на наш цифровой дом', category:'Дизайн', status:'В работе', progress:65, tasks:24, done:16, color:'purple', date:'12 ноября'},
  {id:'2', name:'Мобильное приложение', description:'Продукт, который всегда под рукой', category:'Разработка', status:'В работе', progress:42, tasks:36, done:15, color:'blue', date:'20 ноября'},
  {id:'3', name:'Бренд-платформа', description:'Смыслы и визуальный язык бренда', category:'Маркетинг', status:'На проверке', progress:90, tasks:18, done:16, color:'orange', date:'8 ноября'},
  {id:'4', name:'База знаний', description:'Всё, что нужно знать нашей команде', category:'Команда', status:'В работе', progress:28, tasks:14, done:4, color:'green', date:'25 ноября'},
  {id:'5', name:'Осенняя кампания', description:'Идеи, которые находят свою аудиторию', category:'Маркетинг', status:'Завершён', progress:100, tasks:20, done:20, color:'orange', date:'1 ноября'},
  {id:'6', name:'Дизайн-система', description:'Единый язык для всех продуктов', category:'Дизайн', status:'В работе', progress:74, tasks:32, done:24, color:'purple', date:'18 ноября'},
];
const pages = [{id:'overview' as Page,title:'Обзор',icon:House},{id:'projects' as Page,title:'Проекты',icon:Folder},{id:'settings' as Page,title:'Настройки',icon:Gear}];
function read<T,>(key: string, fallback: T): T {try {const value=localStorage.getItem(key);return value ? JSON.parse(value) : fallback;} catch {return fallback;}}
function useSaved<T,>(key: string, initial: T) {const [value,setValue]=useState<T>(()=>read(key,initial)); useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{}},[key,value]);return [value,setValue] as const;}
function currentPage(): Page {const hash=location.hash.slice(1);return pages.some(p=>p.id===hash)?hash as Page:'overview';}
function Avatar({name, color='purple',small=false}: {name:string;color?:string;small?:boolean}) {return <span className={"'`avatar ${color} ${small?'"'avatar-small':''}"'`} title={name}>{name.split('"' ').map(x=>x[0]).slice(0,2).join('')}</span>;}
function ProjectIcon({project}: {project:Project}) {return <span className={"'`project-icon ${project.color}`}><Icon data={project.category==='"'Разработка'?Smartphone:project.category==='Дизайн'?Palette:project.category==='Команда'?Layers:Globe} size={23}/></span>;}
function OrbitArt(){return <div className=\"orbit-art\" aria-hidden=\"true\"><div className=\"orbit-ring ring-one\"/><div className=\"orbit-ring ring-two\"/><div className=\"orbit-ring ring-three\"/><div className=\"orbit-core\"><Icon data={Layers} size={44}/></div><span className=\"orbit-satellite satellite-one\"><Icon data={CircleCheck} size={22}/></span><span className=\"orbit-satellite satellite-two\"><Icon data={Plus} size={22}/></span><span className=\"orbit-dot dot-one\"/><span className=\"orbit-dot dot-two\"/><span className=\"orbit-star\">✧</span></div>;}

export function App() {
 const [theme,setTheme]=useSaved<'light'|'dark'>('orbita-theme','light');
 const [projects,setProjects]=useSaved<Project[]>('orbita-projects',initialProjects);
 const [profile,setProfile]=useSaved('orbita-profile',{name:'Александр',email:'alexander@orbita.team',workspace:'Моё пространство'});
 const [notifications,setNotifications]=useSaved('orbita-notifications',true);
 const [page,setPage]=useState<Page>(currentPage);
 const [search,setSearch]=useState(''); const [filter,setFilter]=useState('Все проекты');
 const [creating,setCreating]=useState(false);const [name,setName]=useState('');const [description,setDescription]=useState('');const [category,setCategory]=useState('Дизайн');const [error,setError]=useState('');
 const [selected,setSelected]=useState<Project|null>(null);const [help,setHelp]=useState(false);const [showNotifications,setShowNotifications]=useState(false);const [allActivity,setAllActivity]=useState(false);const [listView,setListView]=useState(false);const [toast,setToast]=useState('');
 const [draft,setDraft]=useState(profile);const [narrow,setNarrow]=useState(()=>window.innerWidth<760);
 useEffect(()=>{const onHash=()=>{setPage(currentPage());setSearch('');};window.addEventListener('hashchange',onHash);const onResize=()=>setNarrow(window.innerWidth<760);window.addEventListener('resize',onResize);return()=>{window.removeEventListener('hashchange',onHash);window.removeEventListener('resize',onResize);};},[]);
 useEffect(()=>{document.title="'`${pages.find(p=>p.id===page)?.title} · Орбита`;},[page]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(t);}},[toast]);
 const navigate=(next:Page)=>{location.hash=next;setPage(next);setSearch('');};
 const openCreate=()=>{setName('');setDescription('');setCategory('Дизайн');setError('');setCreating(true);};
 const createProject=(event:React.FormEvent)=>{event.preventDefault();if("'!name.trim()){setError('"'Введите название проекта');return;}const p:Project={id:crypto.randomUUID(),name:name.trim(),description:description.trim()||'Большие идеи начинаются с первого шага',category,status:'В работе',progress:0,tasks:0,done:0,color:category==='Дизайн'?'purple':category==='Разработка'?'blue':category==='Маркетинг'?'orange':'green',date:'Без срока'};setProjects([p,...projects]);setCreating(false);setToast('Проект создан. Время воплощать идеи"'!'"');navigate('projects');setFilter('Все проекты');};
 const filtered=projects.filter(p=>(filter==='Все проекты'||p.status===filter)&&(p.name+' '+p.description).toLowerCase().includes(search.toLowerCase()));
 const projectCard=(p:Project)=><article className=\"project-card\" key={p.id}><div className=\"row between\"><ProjectIcon project={p}/><span className={"'`status ${p.status==='"'На проверке'?'status-review':p.status==='Завершён'?'status-done':''}"'`}><i/>{p.status}</span></div><a className="project-title" href={`#projects`} onClick={e=>{e.preventDefault();setSelected(p);}}><Text variant="subheader-3">{p.name}</Text></a><p className="muted project-description">{p.description}</p><span className="category">{p.category}</span><div className="progress-caption"><span>Прогресс</span><span>{p.progress}%</span></div><div className={`progress-track ${p.color}`} role="progressbar" aria-label={`Прогресс: ${p.name}`} aria-valuenow={p.progress} aria-valuemin={0} aria-valuemax={100}><div style={{width:`${p.progress}%`}}/></div><div className="project-bottom"><div className="avatar-stack"><Avatar name="Анна Смирнова" color="orange" small/><Avatar name="Михаил Котов" color="blue" small/><Avatar name="Елена Волкова" color="green" small/><span className="avatar avatar-small extra-avatar">+2</span></div><span className="task-count"><Icon data={CircleCheck} size={14}/>{p.done}/{p.tasks}</span></div></article>;
 const activity=[{name:'"'Анна Смирнова',color:'orange',text:'завершила задачу',subject:'Главная страница',project:'Редизайн сайта',time:'15 минут назад'}, {name:'Михаил Котов',color:'blue',text:'добавил комментарий',subject:'Авторизация пользователя',project:'Мобильное приложение',time:'42 минуты назад'}, {name:'Елена Волкова',color:'green',text:'обновила статус проекта',subject:'Бренд-платформа',project:'На проверке',time:'1 час назад'}, {name:'Александр',color:'purple',text:'создал задачу',subject:'Обновить библиотеку компонентов',project:'Дизайн-система',time:'2 часа назад'}];
 return <ThemeProvider theme={theme}><AsideHeader className=\"app-shell\" compact={narrow} hideCollapseButton headerDecoration={false}
 logo={{text:'орбита',icon:Layers,iconSize:30,textSize:27,href:'#overview',iconClassName:'brand-icon',className:'brand-logo'}}
 subheaderItems={[{item:{id:'workspace',title:<span className=\"workspace-name\"><span>Моё пространство</span><Icon data={ChevronDown} size={12}/></span>,icon:Layers,iconSize:17,onItemClick:()=>navigate('settings'),className:'workspace-menu'}}]}
